package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TarUtils.computeCheckSum
 */
public class TarUtils_computeCheckSum_TriageGen2Test {





    @Test
    public void testComputeCheckSum_SingleNegativeByte() {
        // In Java, bytes are signed. -1 is 0xFF.
        // The method uses BYTE_MASK (which is 0xFFL) to treat it as unsigned.
        // -1 & 0xFF = 255
        byte[] buf = new byte[]{(byte) 0xFF};
        long expected = 255L;
        long actual = TarUtils.computeCheckSum(buf);
        assertEquals("Checksum should treat bytes as unsigned via BYTE_MASK", expected, actual);
    }






}

